/* The steps of a GSA Multiple Award Schedule (MAS) offer, as the module walks through them. The module re-reads the current solicitation
   refresh before preparing anything; the list here is the outline the prototype shows. */
const GSA = [
  [1, 'Confirm you can apply', 'Two years in business, an active SAM.gov registration with a UEI, and financial statements. Checked against your profile.', 'auto'],
  [2, 'Choose what to offer', 'The Special Item Numbers (SINs) and NAICS codes that match your services. Suggested from your price list: document destruction, under the Office Management category.', 'auto'],
  [3, 'Required training', 'The “Pathways to Success” course and the Readiness Assessment. An officer of the company has to take these; the module links to them and files the certificates.', 'you'],
  [4, 'Financial statements', 'Balance sheet and income statement for the last two years, from your bookkeeping connection.', 'auto'],
  [5, 'Past performance', 'CPARS records, or past performance questionnaires. The module fills a questionnaire for three of your references from the CRM and emails it to each for signature.', 'auto'],
  [6, 'Pricing', 'The price proposal template and the commercial sales practices disclosure, built from your price list and twelve months of invoices, including the discounts your best customers get.', 'auto'],
  [7, 'Technical narratives', 'Corporate experience, quality control and a relevant project for each SIN, drafted from your company information.', 'auto'],
  [8, 'Submit the offer', 'Through GSA’s eOffer system by an authorized negotiator. Choose whether we file as your authorized agent or guide you screen by screen.', 'file'],
  [9, 'After award', 'Upload the price list to GSA Advantage, then report sales and pay the Industrial Funding Fee each quarter. The module prepares each report from your invoices and reminds you.', 'auto']];
const gsaSpec = () => ({ title: 'GSA Schedule', render: page => { const Z = store(), G = Z.gsa, done = GSA.filter(s => G.done[s[0]]).length, re = () => { WD.changed(); page.refresh(); }, edit = owner();
  const act = async s => { if (!edit) return ui.toast('Only an owner or admin can work on the GSA offer', 'lock'); const [n, t, , kind] = s;
    if (kind === 'file') { const v = await ui.actionSheet({ title: 'Submit the offer', message: 'Either way you review everything first, and nothing is submitted without your signature.', buttons: [{ label: 'File it for us', value: 'agent' }, { label: 'Guide me through eOffer', value: 'guide' }] }); if (!v) return; G.mode = v;
      if (v === 'agent') { if (!await ui.alert({ title: 'Authorize us to file', message: 'GSA accepts an offer from an agent only with a signed agent authorization letter. We prepare the letter for your signature, upload every document, and send you the offer to sign before it goes in.', buttons: [{ label: 'Not now', value: false }, { label: 'Prepare the letter', value: true, bold: true }] })) return; G.done[n] = 'Agent letter sent for signature'; }
      else { G.done[n] = 'Guide started'; page.push(guideSpec()); } return re(); }
    if (kind === 'you') { if (await ui.actionSheet({ title: t, message: 'This one has to be done by an officer of the company. Mark it when the certificate arrives.', buttons: [{ label: 'Open the course', value: 'o' }, { label: G.done[n] ? 'Mark not done' : 'Mark done', value: 'd' }] }) === 'd') { G.done[n] = !G.done[n]; re(); } return; }
    if (G.done[n]) return ui.toast('Already prepared. It is in the offer’s documents.', 'checkmark');
    if (await ui.run('Preparing: ' + t.toLowerCase() + '…', () => { G.done[n] = true; }, { done: 'Prepared for your review' })) re(); };
  return ui.list(aiCard({ title: 'GSA Schedule · ' + done + ' of ' + GSA.length + ' steps', text: 'A GSA Schedule lets federal buyers order from you at prices agreed in advance, without a separate bid each time. I prepare each part from what is already in your records and tell you what only you can do.', action: h('div', { style: 'margin-top:10px' }, ui.progress(done / GSA.length)) }),
    h('div', { style: 'border-radius:12px;overflow:hidden;margin:12px 0' }, GSA.map(s => { const d = G.done[s[0]]; return h('div.bp-step', { style: { '--k': d ? '#1B7F3B' : s[3] === 'you' ? '#B25000' : '#8E8E93' }, role: 'button', onclick: () => act(s) }, h('div.n', d ? icon('checkmark', 14) : s[0]), h('div.m', h('b', s[1]), h('span', s[2]), h('span', { style: 'font-weight:600;color:var(--label)' }, d ? (typeof d === 'string' ? d : 'Done') : s[3] === 'you' ? 'Needs you' : s[3] === 'file' ? 'File for us, or be guided' : 'Tap to prepare')), icon('chevron.right', 16, 'var(--label3)')); })),
    note('Typical time from a complete offer to award is several months, and GSA may ask for clarifications along the way; each request shows here with a drafted answer. Requirements follow the current solicitation refresh.')); } });
